<?php
namespace ZinCelestial\Platform\Jobs; use ZinCelestial\Platform\Logging\JobLogger; defined('ABSPATH')||exit;
final class NetworkAggregationJob{const HOOK='zcp_network_aggregate_batch';const RECOVERY='zcp_network_aggregate_recovery';const STATE='zcp_aggregation_state';const RESULTS='zcp_network_diagnostics';
public static function start(int $batch=20):bool{if(!is_multisite()||!current_user_can('manage_network_options'))return false;$batch=max(1,min(100,$batch));update_site_option(self::STATE,array('offset'=>0,'batch'=>$batch,'status'=>'queued','updated'=>time()));if(!wp_next_scheduled(self::HOOK))wp_schedule_single_event(time()+5,self::HOOK,array(0,$batch));if(!wp_next_scheduled(self::RECOVERY))wp_schedule_event(time()+HOUR_IN_SECONDS,'hourly',self::RECOVERY);JobLogger::add('info','Aggregation queued',array('batch'=>$batch));return true;}
public static function run(int $offset=0,int $batch=20):void{if(!JobLock::acquire()){JobLogger::add('warning','Aggregation batch skipped because lock is held',array('offset'=>$offset));return;}try{$sites=get_sites(array('number'=>$batch,'offset'=>$offset,'orderby'=>'id','spam'=>0,'deleted'=>0,'archived'=>0));$r=(array)get_site_option(self::RESULTS,array());foreach($sites as $site){switch_to_blog((int)$site->blog_id);try{$r[(int)$site->blog_id]=array('site_id'=>(int)$site->blog_id,'url'=>esc_url_raw(get_home_url()),'platform_version'=>(string)get_option('zcp_version',''),'theme'=>(string)wp_get_theme()->get('Name'),'updated'=>time());}catch(\Throwable $e){JobLogger::add('error','Site aggregation failed',array('site_id'=>$site->blog_id,'error'=>$e->getMessage()));}finally{restore_current_blog();}}update_site_option(self::RESULTS,$r);$next=$offset+count($sites);$done=count($sites)<$batch;update_site_option(self::STATE,array('offset'=>$next,'batch'=>$batch,'status'=>$done?'complete':'running','updated'=>time()));if(!$done)wp_schedule_single_event(time()+10,self::HOOK,array($next,$batch));else{self::prune();JobLogger::add('info','Aggregation completed',array('sites'=>count($r)));}}catch(\Throwable $e){update_site_option(self::STATE,array('offset'=>$offset,'batch'=>$batch,'status'=>'failed','updated'=>time()));JobLogger::add('error','Aggregation batch failed',array('offset'=>$offset,'error'=>$e->getMessage()));}finally{JobLock::release();}}
public static function recover():void{$s=(array)get_site_option(self::STATE,array());if(JobLock::stale())JobLock::release();if(in_array($s['status']??'',array('running','queued','failed'),true)&&(int)($s['updated']??0)<time()-15*MINUTE_IN_SECONDS&&!wp_next_scheduled(self::HOOK)){wp_schedule_single_event(time()+5,self::HOOK,array((int)($s['offset']??0),(int)($s['batch']??20)));JobLogger::add('warning','Stale aggregation recovered',array('offset'=>$s['offset']??0));}JobLogger::prune(14);self::prune();}
private static function prune():void{$cut=time()-30*DAY_IN_SECONDS;$r=(array)get_site_option(self::RESULTS,array());update_site_option(self::RESULTS,array_filter($r,fn($x)=>(int)($x['updated']??0)>=$cut));}public static function status():array{return array('state'=>(array)get_site_option(self::STATE,array()),'sites'=>(array)get_site_option(self::RESULTS,array()),'errors'=>JobLogger::all());}}
